package org.eclipse.debug.ui.launchview.internal.impl;

import java.io.File;
import org.eclipse.debug.core.ILaunchConfiguration;
import org.eclipse.debug.ui.launchview.internal.launcher.StandaloneLaunchConfigExecutor;

public class DebugCoreLaunchObject {
    ILaunchConfiguration config;
    public void launch(String mode, boolean build, boolean wait, File logFile) {
        StandaloneLaunchConfigExecutor.launchProcess(config, mode, build, wait, logFile);
    }
}

afterExample:
package org.eclipse.debug.ui.launchview.internal.impl;

import java.io.File;
import org.eclipse.debug.core.ILaunchConfiguration;
import org.eclipse.debug.ui.launchview.LaunchConfigurationViewPlugin;

public class DebugCoreLaunchObject {
    ILaunchConfiguration config;
    public void launch(String mode, boolean build, boolean wait, File logFile) {
        LaunchConfigurationViewPlugin.getExecutor().launchProcess(config, mode, build, wait, logFile);
    }
}

